<?php
namespace App\Http\Controllers; use App\Models\CatalogItem; use Illuminate\Http\Request;
class CatalogItemController extends Controller { public function index(){return view('catalog.index',['items'=>CatalogItem::with('category')->orderBy('name')->get(),'categories'=>\App\Models\Category::where('active',true)->orderBy('name')->get()]);} public function store(Request $request){CatalogItem::create($request->validate(['type'=>['required','in:product,service'],'name'=>['required'],'code'=>['required','unique:catalog_items,code'],'category_id'=>['nullable','exists:categories,id'],'brand'=>['nullable'],'model'=>['nullable'],'unit'=>['required'],'price'=>['required','numeric','min:0'],'stock'=>['required_if:type,product','integer','min:0']]));return redirect()->route('catalog.index');} }
